  def admin_nav_link(label, path, icon_name = nil)
    active = current_page?(path)
    css = class_names(
      "flex items-center gap-3 rounded-lg px-3 py-2 text-sm font-medium transition-colors",
      "bg-[var(--color-primary)]/10 text-[var(--color-primary)]" => active,
      "text-[var(--color-muted-foreground)] hover:bg-[var(--color-muted)] hover:text-[var(--color-foreground)]" => !active
    )
    icon_html = ADMIN_NAV_ICONS[icon_name] || ""
    link_to path, class: css do
      (icon_html + content_tag(:span, label)).html_safe
    end
  end
